constraints:
1 ≤ N*M ≤ 10^{6}

expected time complexity: O(M*N)
expected auxiliary space: O(M*N)

standard_solution_code:
def bfs(tr, tc, grid, dis):
	(n, m) = (len(grid), len(grid[0]))
	visit = [[0] * m for _ in range(n)]
	q = []
	q.append((tr, tc, 0))
	visit[tr][tc] = 1
	while q:
		(r, c, s) = q.pop(0)
		if grid[r][c] == 'B':
			dis[tr][tc] = s
			break
		l = [[-1, 0], [1, 0], [0, -1], [0, 1]]
		for (i, j) in l:
			(nr, nc) = (r + i, c + j)
			if nr < n and nr >= 0 and (nc < m) and (nc >= 0) and (grid[nr][nc] != 'W') and (not visit[nr][nc]):
				visit[nr][nc] = 1
				q.append((nr, nc, s + 1))

class Solution:

	def findDistance(self, grid, m, n):
		dis = [[-1] * n for _ in range(m)]
		for i in range(m):
			for j in range(n):
				if grid[i][j] == 'O':
					bfs(i, j, grid, dis)
				elif grid[i][j] == 'B':
					dis[i][j] = 0
		return dis
